"""Independent, dependency-free evidence supplement. Existing application untouched."""
import html
import json
from pathlib import Path
P = Path(__file__).resolve().parent
e = lambda v: html.escape(str(v), quote=True)
rows = json.loads((P / 'evidence.json').read_text())
nav = '<nav aria-label="Audit navigation"><a href="../../index.html">← Main dashboard</a><a href="index.html">Executive audit</a><a href="creative.html">Creative</a><a href="gaming.html">Gaming</a><a href="research.html">Research platforms</a><a href="review.html">Flagged for Review</a></nav>'
def table(rs):
    heads = ['Entry / category', 'Entry fee', 'Cash award', 'Dates as published', 'Eligibility / AI restrictions', 'Finding / unresolved', 'Official source']
    s = '<div class="table-scroll" tabindex="0" role="region" aria-label="Evidence comparison table"><table><caption>Official pages read November 1, 2026. Blank cells are unverified, not unrestricted.</caption><thead><tr>' + ''.join('<th scope="col">'+h+'</th>' for h in heads) + '</tr></thead><tbody>'
    for r in rs:
        s += '<tr>'
        for key in ['name', 'fee', 'prize', 'dates', 'eligibility_ai', 'finding']:
            s += '<td>' + ('<strong>'+e(r[key])+'</strong>' if key == 'name' else e(r[key])) + '</td>'
        s += '<td>' + ''.join('<a href="'+e(u)+'" rel="noopener noreferrer">Official source '+str(i+1)+' ↗</a>' for i,u in enumerate(r['sources'])) + '<details><summary>Evidence excerpt</summary><blockquote>'+e(r['excerpt'])+'</blockquote></details></td></tr>'
    return s+'</tbody></table></div>'
def page(name, title, intro, body):
    (P / name).write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Independent official-source competition verification supplement, November 1 2026."><title>'+e(title)+' | PrizeDesk Audit</title><link rel="stylesheet" href="audit.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html"><span>P</span> PrizeDesk <small>FIELD NOTES / 01</small></a>'+nav+'</header><main id="main"><p class="eyebrow">INDEPENDENT VERIFICATION · 01 NOVEMBER 2026</p><h1>'+e(title)+'</h1><p class="lead">'+e(intro)+'</p>'+body+'</main><footer>Field-specific evidence, not an endorsement. No accounts created or entries submitted. <a href="evidence.json">Download evidence JSON</a> · <a href="REPORT.md">Audit report</a></footer></body></html>')
summary = '''<section class="metrics" aria-label="Supplement scope"><article><strong>13</strong><span>Inherited leads checked</span></article><article><strong>2</strong><span>Clear free-entry cash paths*</span></article><article><strong>13</strong><span>Rows retain review flags</span></article></section><p class="note">*Wergle Flomp and Sony Single Image have explicit free-entry and cash-award language. This is not full legal qualification or payment verification. Their remaining flags appear below. These are a subset of the main ledger, not 13 additional competitions.</p><section class="cards"><article><p class="eyebrow">BEST DOCUMENTED / WRITING</p><h2>Wergle Flomp</h2><p>No entry fee. $2,000 first prize; $5,100 cash pool. Submissions through April 1, 2027. One English humor poem, at most 250 lines. AI-generated text is prohibited; limited critique is allowed and AI use must be disclosed.</p><a href="https://winningwriters.com/our-contests/wergle-flomp-humor-poetry-contest-free">Read official rules ↗</a></article><article><p class="eyebrow">BEST DOCUMENTED / PHOTOGRAPHY</p><h2>Sony Single Image</h2><p>Three free images. $5,000 USD overall award. Deadline January 5, 2027, 16:00 GMT. Images must be taken in 2026 and originate as photographs—not computer-generated content. Payment mechanics remain unverified.</p><a href="https://www.worldphoto.org/sony-world-photography-awards/single-image">Read official rules ↗</a></article></section><section class="notice"><h2>What this means for AI-assisted competing</h2><p>Neither highlighted path permits outsourcing the submission to generative AI. A coding agent can help organize rules and research, but cannot assume permission to generate the entry. Do not spend on compute or buy extra submissions before resolving event-specific restrictions.</p><p>These are research priorities based on documented entry paths, not expected earnings rankings. We have no verified odds, payout history, or hourly-return estimates.</p></section>'''
page('index.html','Better evidence. Fewer false starts.','A targeted second-pass audit of the supplied ledger. Official rules separate real opportunities from fees, bonus currency and stale destinations.',summary+'<h2>All supplemental findings</h2>'+table(rows))
for cat,title in [('creative','Creative competitions'),('gaming','Gaming & sports'),('research','Research platforms & directories')]:
    page(cat+'.html',title,'Field-by-field findings from official organizer pages. Every unresolved value stays blank.',table([r for r in rows if r['category']==cat]))
page('review.html','Flagged for Review','Published issues do not block release. Every row has an official source and an explicit remaining verification scope.','<section class="notice"><h2>Do not silently repair or infer</h2><p>A fetched page is not proof of payment. General platform policies do not establish an individual event’s qualifications. A source-page conflict remains a conflict until the organizer resolves it.</p><p>The main dashboard may continue to show older blank fields until its owning integration session incorporates this supplement. The findings here are intentionally independent.</p></section>'+table(rows))
print('Built five independent audit pages from',len(rows),'evidence records.')
